SELECT status, CASE WHEN shipping_fee >= 38 THEN 'high' WHEN shipping_fee >= 5 THEN 'mid' ELSE 'low' END AS shipping_fee_bucket, CASE WHEN amount >= 1220 THEN 'high' WHEN amount >= 310 THEN 'mid' ELSE 'low' END AS amount_bucket, SUM(CASE WHEN status = 'CANCELLED' THEN 1 ELSE 0 END) AS cancelled_count, SUM(CASE WHEN status = 'RETURNED' THEN 1 ELSE 0 END) AS returned_count FROM orders WHERE order_date <= '2025-06-01' AND (order_date BETWEEN '2025-01-01' AND '2025-07-01' OR customer_id = 11) GROUP BY 1, 2, 3 HAVING SUM(CASE WHEN status = 'RETURNED' THEN 1 ELSE 0 END) > 43
